<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $product=null;$orders=false;$buyers=false;$error="";if($_SERVER['REQUEST_METHOD']=='POST'){$id=trim($_POST['product_id']??'');if(!ctype_digit($id)||(int)$id<1||strlen($id)>8)$error="Please enter a valid product ID.";else{$id=(int)$id;$p=mysqli_query($conn,"SELECT id,name FROM products WHERE id=$id");if($p&&mysqli_num_rows($p)>0){$product=mysqli_fetch_assoc($p);$orders=mysqli_query($conn,"SELECT DISTINCT o.id order_id FROM orders o JOIN order_items oi ON o.id=oi.order_id WHERE oi.product_id=$id ORDER BY o.id");$buyers=mysqli_query($conn,"SELECT DISTINCT c.id,c.name,c.salary FROM customers c JOIN orders o ON c.id=o.customer_id JOIN order_items oi ON o.id=oi.order_id WHERE oi.product_id=$id ORDER BY c.salary DESC");}else $error="Product not found.";}} ?>
<h2>Product Sales Details</h2><form method="POST" class="row g-2 my-3"><div class="col-sm-5"><input type="number" name="product_id" min="1" max="99999999" class="form-control" placeholder="Enter product ID" required></div><div class="col-sm-3"><button class="btn btn-primary">Show Details</button></div></form><?php if($error): ?><div class="alert alert-warning"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if($product): ?><div class="card p-3 mb-3"><h4><?php echo htmlspecialchars($product['name']); ?></h4><p class="mb-0"><b>Product ID:</b> <?php echo $product['id']; ?></p><p class="mb-0"><b>Number Of Orders Sold In:</b> <?php echo mysqli_num_rows($orders); ?></p></div><h4>Order Numbers</h4><ul class="list-group mb-4"><?php if(mysqli_num_rows($orders)>0): while($o=mysqli_fetch_assoc($orders)): ?><li class="list-group-item">Order #<?php echo $o['order_id']; ?></li><?php endwhile; else: ?><li class="list-group-item">This product has not been sold.</li><?php endif; ?></ul><h4>Customers Who Bought This Product (Richest First)</h4><div class="table-responsive"><table class="table table-bordered table-striped bg-white"><thead class="table-dark"><tr><th>Customer ID</th><th>Customer Name</th><th>Salary</th></tr></thead><tbody><?php if(mysqli_num_rows($buyers)>0): while($b=mysqli_fetch_assoc($buyers)): ?><tr><td><?php echo $b['id']; ?></td><td><?php echo htmlspecialchars($b['name']); ?></td><td><?php echo number_format($b['salary'],2); ?></td></tr><?php endwhile; else: ?><tr><td colspan="3">No customers found.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>